    #projects { list-style: none; padding: 0; margin: 24px 0; display: grid; gap: 10px; }
    [data-testid="project-row"] { display: flex; justify-content: space-between; align-items: center; gap: 16px; padding: 14px 16px; border: 1px solid #d6dce6; border-radius: 8px; background: white; }
  </style>
</head>
<body>
  <main id="project-list">
    <h1>Workboard</h1>
    <form id="create-form">
      <label>Project name<input id="project-name" name="name" type="text" autocomplete="off"></label>
      <button type="submit">Create project</button>
    </form>
    <p id="alert" role="alert" hidden></p>
    <ul id="projects" aria-label="Projects"></ul>
  </main>
  <main id="project-detail" hidden>
    <button id="back-button" class="secondary" type="button">Projects</button>
    <h1 id="project-title"></h1>
  </main>
  <script>
    const listView = document.querySelector('#project-list');
    const detailView = document.querySelector('#project-detail');
    const rows = document.querySelector('#projects');
    const alertMessage = document.querySelector('#alert');

    async function loadProjects() {
      const response = await fetch('/api/projects');
      const projects = await response.json();
      rows.replaceChildren();
      for (const project of projects) {
        const row = document.createElement('li');
        row.dataset.testid = 'project-row';
        const name = document.createElement('span');
        name.textContent = project.name;
        const open = document.createElement('button');
        open.type = 'button';
        open.textContent = 'Open project';
        open.addEventListener('click', () => { window.location.href = `/projects/${encodeURIComponent(project.id)}`; });
        row.append(name, open);
        rows.append(row);
      }
    }

    async function showProject() {
      const match = window.location.pathname.match(/^\/projects\/([^/]+)$/);
      if (!match) return false;
      const response = await fetch(`/api/projects/${encodeURIComponent(decodeURIComponent(match[1]))}`);
      if (!response.ok) {
        document.querySelector('#project-title').textContent = 'Project not found';
      } else {
        const project = await response.json();
        document.querySelector('#project-title').textContent = project.name;
      }
      listView.hidden = true;
      detailView.hidden = false;
      return true;
    }

    document.querySelector('#create-form').addEventListener('submit', async (event) => {
      event.preventDefault();
      const input = document.querySelector('#project-name');
      const name = input.value.trim();
      if (!name) {
        alertMessage.textContent = 'Project name is required';
        alertMessage.hidden = false;
        input.focus();
        return;
      }
      const response = await fetch('/api/projects', {
        method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ name })
      });
      if (!response.ok) {
        const result = await response.json();
        alertMessage.textContent = result.error || 'Unable to create project';
        alertMessage.hidden = false;
        return;
      }
      input.value = '';
      alertMessage.hidden = true;
      await loadProjects();
    });
    document.querySelector('#back-button').addEventListener('click', () => { window.location.href = '/'; });
    if (!(await showProject())) await loadProjects();
  </script>
</body>
</html>
